param([ValidateRange(640,16384)][int]$Width=3440,[ValidateRange(480,8640)][int]$Height=1440)
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot;$dll=Join-Path $root 'FireProject_Data\Managed\Scripts.dll';$bak="$dll.embr-smooth-motion.bak";$cecil=Join-Path $root '.modtools\ilspy\Mono.Cecil.dll'
if(!(Test-Path $bak)){Copy-Item $dll $bak};Add-Type -Path $cecil
$r=New-Object Mono.Cecil.DefaultAssemblyResolver;$r.AddSearchDirectory((Split-Path $dll));$p=New-Object Mono.Cecil.ReaderParameters;$p.AssemblyResolver=$r;$a=[Mono.Cecil.AssemblyDefinition]::ReadAssembly($dll,$p);$o=$a.MainModule.Types|? FullName -eq 'UITabletAudioVideoSetting';$ro=$o.NestedTypes|? Name -eq 'ResolutionOptions';$sr=$ro.NestedTypes|? Name -eq 'SettingResolution';$ctor=$ro.Methods|? Name -eq '.ctor';$mode=$sr.Methods|? Name -eq 'set_mode';$mc=$ctor.Body.Instructions|?{$_.Operand -and $_.Operand.FullName -eq $mode.FullName}|select -First 1
$gi=($ctor.Body.Instructions|?{$_.Operand -and $_.Operand.Name -eq 'get_Item'}|select -First 1).Operand;$field=$ro.Fields|? Name -eq 'options';$il=$ctor.Body.GetILProcessor();$anchor=$mc.Next
foreach($d in @(@(($sr.Methods|? Name -eq 'set_width'),$Width),@(($sr.Methods|? Name -eq 'set_height'),$Height))){$il.InsertBefore($anchor,$il.Create([Mono.Cecil.Cil.OpCodes]::Ldarg_0));$il.InsertBefore($anchor,$il.Create([Mono.Cecil.Cil.OpCodes]::Ldfld,$field));$il.InsertBefore($anchor,$il.Create([Mono.Cecil.Cil.OpCodes]::Ldc_I4_0));$il.InsertBefore($anchor,$il.Create([Mono.Cecil.Cil.OpCodes]::Callvirt,$gi));$il.InsertBefore($anchor,$il.Create([Mono.Cecil.Cil.OpCodes]::Ldc_I4,[int]$d[1]));$il.InsertBefore($anchor,$il.Create([Mono.Cecil.Cil.OpCodes]::Callvirt,$d[0]))}
$tmp="$dll.embr-smooth-motion.tmp";$a.Write($tmp);$a.Dispose();Move-Item $tmp $dll -Force;Write-Host "Windowed Fullscreen installed at ${Width}x${Height}."
